@extends('tenant.layout')
@php($labels=['CREATED'=>'Envío creado','READY_FOR_PICKUP'=>'Recolección solicitada','PICKED_UP'=>'Recolectado','IN_TRANSIT'=>'En tránsito','OUT_FOR_DELIVERY'=>'En reparto','DELIVERED'=>'Entregado','DELIVERY_FAILED'=>'No entregado','CANCELED'=>'Cancelado'])
@section('title','Rastreo '.$trackingResult['tracking_number'])
@section('content')
@php($steps=['CREATED'=>'Creado','PICKED_UP'=>'Recolectado','IN_TRANSIT'=>'En tránsito','OUT_FOR_DELIVERY'=>'En reparto','DELIVERED'=>'Entregado'])
@php($order=array_keys($steps))
@php($current=array_search($trackingResult['status'],$order,true))
@php($exception=in_array($trackingResult['status'],['DELIVERY_FAILED','CANCELED'],true))
@php($last=collect($trackingResult['events'])->sortByDesc('occurred_at')->first())
<div style="max-width:900px;margin:1rem auto"><a href="/rastreo">← Consultar otra guía</a><header class="z-page-header" style="margin-top:1rem"><div><div class="z-eyebrow">RASTREO DE ENVÍO</div><h1>{{ $trackingResult['tracking_number'] }}</h1><p class="z-muted">Última actualización: {{ optional($last['occurred_at'] ?? null)->format('d/m/Y H:i') ?: 'Sin movimientos' }}</p></div><span class="z-badge @if($trackingResult['status']==='DELIVERED') z-badge--success @elseif($exception) z-badge--danger @endif">{{ $labels[$trackingResult['status']] ?? 'Actualización de envío' }}<span class="z-sr-only">{{ str_replace('_',' ',$trackingResult['status']) }}</span></span></header><section class="z-panel">@if($exception)<div class="z-alert z-alert--danger"><strong>{{ $trackingResult['status']==='CANCELED'?'Envío cancelado':'No fue posible completar la entrega' }}</strong><p>Consulta el historial para conocer la última actualización.</p></div>@else<ol class="z-progress">@foreach($steps as $code=>$copy)@php($index=array_search($code,$order,true))<li class="@if($current!==false&&$index<$current) is-complete @elseif($index===$current) is-current @endif">{{ $copy }}</li>@endforeach</ol>@endif<h2 class="z-section-title" style="margin-bottom:1rem">Historial detallado</h2>@if(collect($trackingResult['events'])->isEmpty())<div class="z-empty"><p>Aún no hay movimientos disponibles.</p></div>@else<ol class="z-timeline">@foreach(collect($trackingResult['events'])->sortByDesc('occurred_at') as $event)<li><strong>{{ $labels[$event['status']] ?? 'Actualización de envío' }}</strong><span class="z-sr-only">{{ str_replace('_',' ',$event['status']) }}</span>@if($event['status']==='DELIVERY_FAILED')<div>Intento de entrega no completado</div>@endif<div class="z-muted">{{ optional($event['occurred_at'])->format('d/m/Y H:i') }}</div></li>@endforeach</ol>@endif</section><div style="margin-top:1rem"><a class="z-btn z-btn--outline" href="/rastreo"><x-zigo.icon name="search" />Consultar otra guía</a></div></div>
@endsection
